const filas = $input.all().map((i) => i.json).filter((r) => r.sku);
if (filas.length === 0) return [];
const fmt = (n) => Number(n).toLocaleString('es-AR', { minimumFractionDigits: 2 });
const tabla = filas
  .map((r) => `<tr><td>${r.sku}</td><td>${r.descripcion}</td><td align="right">$ ${fmt(r.anterior)}</td><td align="right">$ ${fmt(r.actual)}</td><td align="right"><b>${r.variacion_pct > 0 ? '+' : ''}${r.variacion_pct} %</b></td></tr>`)
  .join('');
const html =
  `<p>Variaciones de precio del proveedor desde la última carga (${filas.length}):</p>` +
  `<table border="1" cellpadding="6" cellspacing="0"><tr><th>SKU</th><th>Repuesto</th><th>Antes</th><th>Ahora</th><th>Variación</th></tr>${tabla}</table>`;
return [{ json: { clave: filas[0].clave, para: filas[0].email_compras, asunto: `Precios de repuestos: ${filas.length} variación(es) importantes`, html }, pairedItem: { item: 0 } }];
